def compute(vars):
    value_2017_millions = vars["v1"] * 1000
    value_2016_millions = vars["v2"] * 1000
    value_2015_millions = vars["v3"]
    total_millions = value_2017_millions + value_2016_millions + value_2015_millions

    return {
        "value": total_millions,
        "trace": {
            "value_2017_millions": value_2017_millions,
            "value_2016_millions": value_2016_millions,
            "value_2015_millions": value_2015_millions,
            "total_millions": total_millions,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
